private readonly ConcurrentDictionary<string, int> _hits = new();
private long _total;
private readonly object _gate = new();
private string _slowestPath = "";
private long _slowestMs;

public void Record(string path, long elapsedMs)
{
    _hits.AddOrUpdate(path, 1, (_, current) => current + 1);  // atomic per key
    Interlocked.Increment(ref _total);                        // atomic counter

    lock (_gate)                                              // two fields, one invariant
    {
        if (elapsedMs > _slowestMs) { _slowestMs = elapsedMs; _slowestPath = path; }
    }
}
